def solve(pred_name, cascade_modes, stop='fix'):
    # pred functions
    preds={
      'up0': lambda i,j: i==0 or I[i-1,j]==0,
      'left0': lambda i,j: j==0 or I[i,j-1]==0,
      'runleftend': lambda i,j: j==0 or I[i,j-1]!=1,
      'runrightend': lambda i,j: j==W-1 or I[i,j+1]!=1,
      'abovePainted': lambda i,j: i==0 or O[i-1,j]!=I[i-1,j] and I[i-1,j]==1,
      'belowPainted': lambda i,j: i==H-1 or O[i+1,j]!=I[i+1,j] and I[i+1,j]==1,
      '2x2tl': lambda i,j: False, # placeholder
    }
    P=preds[pred_name]
    paint=set()
    for i in range(H):
        for j in range(W):
            if I[i,j]==1 and P(i,j): paint.add((i,j))
    if stop=='onepass': return paint
    changed=True
    while changed:
        changed=False
        for mode in cascade_modes:
            for di,dj in ((1,0),(0,1)):
                for ci,cj in list(paint):
                    i,j=ci+di,cj+dj
                    if 0<=i<H and 0<=j<W and I[i,j]==1:
                        ok=True
                        if mode==('L','D'):
                            ok &= I[i,j-1]==1 and I[i+1,j]==1
                        elif mode==('L',): ok &= I[i,j-1]==1
                        elif mode==('D',): ok &= I[i+1,j]==1
                        elif mode==('always',): ok=True
                        if ok and (i,j) not in paint:
