from collections import deque
def comps(gv):
    seen=np.zeros(len(gv),bool); out=[]
    for i in range(len(gv)):
        for j in range(len(gv[0])):
            if gv[i][j]==1 and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=True; c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<len(gv) and 0<=b<len(gv[0]) and gv[a][b]==1 and not seen[a,b]:
                            seen[a,b]=True; q.append((a,b))
                out.append(c)
    return out
