import numpy as np
from collections import deque
def f(gi):
    g=np.array(gi); H,W=g.shape
    # strays: cells not 0 or 1
    strays=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j] not in (0,1)]
    new=g.copy()
    for si,sj,col in strays:
        # find the enclosed region(s) containing this stray: flood fill from stray over cells !=0 that don't reach border
        q=deque([(si,sj)]); seen=set()
        while q:
            y,x=q.popleft()
            if (y,x) in seen: continue
            seen.add((y,x))
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    a,b=y+dy,x+dx
                    if 0<=a<H and 0<=b<W and (a,b) not in seen and g[a][b]!=0:
                        q.append((a,b))
